import unittest


class TestSafeCalculateNormalCases(unittest.TestCase):
    def test_addition_and_multiplication_precedence(self):
        self.assertAlmostEqual(safe_calculate("2 + 3 * 4"), 14.0)

    def test_parentheses_and_division(self):
        self.assertAlmostEqual(safe_calculate("(1 + 2) / 4"), 0.75)

    def test_unary_minus_with_parentheses_and_float(self):
        self.assertAlmostEqual(safe_calculate("-(3 - 5) * 2.5"), 5.0)

    def test_whitespace_ignored(self):
        self.assertAlmostEqual(safe_calculate("  1   +\t2\n* 3 "), 7.0)

    def test_float_literals_and_leading_dot(self):
        self.assertAlmostEqual(safe_calculate(".5 + 1.5"), 2.0)

    def test_unary_plus(self):
        self.assertAlmostEqual(safe_calculate("+5 - +2"), 3.0)

    def test_returns_float_type(self):
        result = safe_calculate("1 + 1")
        self.assertIsInstance(result, float)


class TestSafeCalculateErrors(unittest.TestCase):
    def test_empty_input_raises_value_error(self):
        with self.assertRaises(ValueError):
            safe_calculate("")

    def test_whitespace_only_raises_value_error(self):
        with self.assertRaises(ValueError):
            safe_calculate("   \t\n ")

    def test_division_by_zero_raises(self):
        with self.assertRaises(ZeroDivisionError):
            safe_calculate("2 / 0")

    def test_division_by_zero_in_subexpression(self):
        with self.assertRaises(ZeroDivisionError):
            safe_calculate("1 / (3 - 3)")

    def test_invalid_syntax_raises_value_error(self):
        for expr in ["1 +", "(1 + 2", "1 2", "* 3", "1 + * 2", "()"]:
            with self.subTest(expr=expr):
                with self.assertRaises(ValueError):
                    safe_calculate(expr)

    def test_malformed_number_literal_raises(self):
        for expr in ["1.2.3", "."]:
            with self.subTest(expr=expr):
                with self.assertRaises(ValueError):
                    safe_calculate(expr)

    def test_length_limit_exceeded_raises_value_error(self):
        expr = "1 + " * 60 + "1"  # well over 200 characters
        self.assertGreater(len(expr), 200)
        with self.assertRaises(ValueError):
            safe_calculate(expr)

    def test_length_limit_boundary_allowed(self):
        # Build an expression of exactly 200 characters that is valid.
        expr = "1" + " + 1" * 49  # 1 + 4*49 = 197 chars
        expr = expr + " " * (200 - len(expr))
        self.assertEqual(len(expr), 200)
        self.assertAlmostEqual(safe_calculate(expr), 50.0)


class TestSafeCalculateMaliciousInputs(unittest.TestCase):
    def test_import_call_rejected(self):
        with self.assertRaises(ValueError):
            safe_calculate("__import__('os').system('ls')")

    def test_names_and_attributes_rejected(self):
        for expr in ["os.system('ls')", "a + b", "x", "1 .real"]:
            with self.subTest(expr=expr):
                with self.assertRaises(ValueError):
                    safe_calculate(expr)

    def test_power_operator_rejected(self):
        with self.assertRaises(ValueError):
            safe_calculate("2 ** 3")

    def test_string_literals_rejected(self):
        for expr in ["'abc'", '"abc"', "1 + 'a'"]:
            with self.subTest(expr=expr):
                with self.assertRaises(ValueError):
                    safe_calculate(expr)

    def test_non_string_input_rejected(self):
        for value in [None, 123, 1.5, ["1 + 1"], {"a": 1}]:
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    safe_calculate(value)


if __name__ == "__main__":
    unittest.main()

